package com.spendwise.auth;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;import java.util.Map;
@Service public class AuthService{private final AppUserRepository users;private final PasswordEncoder encoder;private final SecretKey key;
public AuthService(AppUserRepository u,PasswordEncoder e,@Value("${JWT_SECRET:change-this-development-secret-before-production-2026}")String secret){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must be at least 32 bytes");users=u;encoder=e;key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}
@Transactional public Map<String,Object> register(String name,String email,String password){String e=email.trim().toLowerCase();if(users.existsByEmailIgnoreCase(e))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists");return token(users.save(new AppUser(name.trim(),e,encoder.encode(password))));}
public Map<String,Object> login(String email,String password){AppUser u=users.findByEmailIgnoreCase(email.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(password,u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return token(u);}
private Map<String,Object> token(AppUser u){Instant now=Instant.now();String t=Jwts.builder().subject(u.getEmail()).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(86400))).signWith(key).compact();return Map.of("token",t,"name",u.getName(),"email",u.getEmail(),"expiresAt",now.plusSeconds(86400).toString());}
public String verify(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}